```cpp
#include <iostream>
using namespace std;

// Recursive function to find the nth number in the sequence
int sequence(int n) {
    // Base cases - first three numbers in the sequence
    if (n == 1) {
        return 0;
    }
    if (n == 2) {
        return -1;
    }
    if (n == 3) {
        return -1;
    }

    // Recursive case: each number is the sum of the three preceding ones
    return sequence(n - 1) + sequence(n - 2) + sequence(n - 3);
}

int main() {
    int n;

    cout << "Enter the position of the number in the sequence (n): ";
    cin >> n;

    // Validate input
    if (n < 1) {
        cout << "Error: The sequence is defined only for positive positions." << endl;
        return 1;
    }

    // Calculate and display the nth number in the sequence
    cout << "The " << n << "th number in the sequence is: " << sequence(n) << endl;

    return 0;
}
```

